-- Schema created by server.py from v17 commit 3e153da, captured via sqlite_master.
-- No user data or secrets are included.

CREATE TABLE assets(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,filename TEXT NOT NULL,stored_path TEXT NOT NULL,external_url TEXT NOT NULL DEFAULT '',mime TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL);

CREATE TABLE bookmarks(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,opportunity_id INTEGER NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE,created_at TEXT NOT NULL,PRIMARY KEY(user_id,opportunity_id));

CREATE TABLE course_enrolments(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,course_key TEXT NOT NULL,kind TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,course_key,kind));

CREATE TABLE email_tokens(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,purpose TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,used_at TEXT NOT NULL DEFAULT '');

CREATE TABLE feed_sources(id INTEGER PRIMARY KEY AUTOINCREMENT,url TEXT NOT NULL UNIQUE,added_at TEXT NOT NULL,last_fetched TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1);

CREATE TABLE moderation_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,admin_id INTEGER REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);

CREATE TABLE opportunities(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,title TEXT NOT NULL UNIQUE,provider TEXT NOT NULL,country TEXT NOT NULL,level TEXT NOT NULL,deadline TEXT NOT NULL,url TEXT NOT NULL,summary TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL, auto_description TEXT NOT NULL DEFAULT '');

CREATE TABLE opportunity_submissions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT NOT NULL,provider TEXT NOT NULL,country TEXT NOT NULL,level TEXT NOT NULL,deadline TEXT NOT NULL,url TEXT NOT NULL,summary TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,reviewed_at TEXT NOT NULL DEFAULT '', source_mode TEXT NOT NULL DEFAULT 'manual', fetched_summary TEXT NOT NULL DEFAULT '', fetched_image TEXT NOT NULL DEFAULT '');

CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT,pledge_id INTEGER NOT NULL REFERENCES pledges(id) ON DELETE CASCADE,provider TEXT NOT NULL,reference TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',checkout_url TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);

CREATE TABLE pledges(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,name TEXT NOT NULL,email TEXT NOT NULL,amount REAL NOT NULL,message TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pledged',created_at TEXT NOT NULL, platform_fee REAL NOT NULL DEFAULT 0, creator_amount REAL NOT NULL DEFAULT 0);

CREATE TABLE project_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,name TEXT NOT NULL,email TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);

CREATE TABLE projects(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,category TEXT NOT NULL,summary TEXT NOT NULL,details TEXT NOT NULL,goal_amount REAL NOT NULL DEFAULT 0,price REAL NOT NULL DEFAULT 0,asset_url TEXT NOT NULL DEFAULT '',demo_url TEXT NOT NULL DEFAULT '',repo_url TEXT NOT NULL DEFAULT '',mobile_money_name TEXT NOT NULL DEFAULT '',mobile_money_number TEXT NOT NULL DEFAULT '',mobile_money_network TEXT NOT NULL DEFAULT '',payout_notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);

CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);

CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);

CREATE TABLE sync_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,source TEXT NOT NULL,imported INTEGER NOT NULL DEFAULT 0,message TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);

CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student',email_verified INTEGER NOT NULL DEFAULT 0,profile_photo_url TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL, account_type TEXT NOT NULL DEFAULT '', career TEXT NOT NULL DEFAULT '', education_level TEXT NOT NULL DEFAULT '');
